DROP TABLE IF EXISTS `aircraft`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `aircraft` (
  `idaircraft` int unsigned NOT NULL AUTO_INCREMENT,
  `tailnumber` varchar(30) NOT NULL DEFAULT '',
  `tailNormal` varchar(30) DEFAULT NULL COMMENT 'Normalized tail (no hyphens) - suitable for searching',
  `version` int NOT NULL DEFAULT '0' COMMENT 'The version of this aircraft (e.g., if multiple aircraft share a tailnumber)',
  `idmodel` int unsigned NOT NULL DEFAULT '0',
  `InstanceType` int unsigned NOT NULL DEFAULT '1' COMMENT 'InstanceType of this airplane (real vs. simulator)',
  `LastAnnual` datetime DEFAULT NULL COMMENT 'Date of last annual inspection',
  `LastPitotStatic` datetime DEFAULT NULL COMMENT 'Date of last PitotStatic inspection',
  `LastVOR` datetime DEFAULT NULL COMMENT 'Date of last VOR inspection',
  `LastAltimeter` datetime DEFAULT NULL COMMENT 'Date of last altimeter inspection',
  `LastTransponder` datetime DEFAULT NULL COMMENT 'Date of last transponder inspection',
  `LastELT` datetime DEFAULT NULL COMMENT 'Date of last ELT inspection',
  `Last100` decimal(10,1) unsigned NOT NULL DEFAULT '0.0' COMMENT 'Hobbs of last 100hr inspection',
  `LastOil` decimal(10,1) unsigned NOT NULL DEFAULT '0.0' COMMENT 'Hobbs of last oil change',
  `LastEngine` decimal(10,1) unsigned NOT NULL DEFAULT '0.0' COMMENT 'Engine time',
  `RegistrationDue` datetime DEFAULT NULL COMMENT 'Date, if any, of next renewal of registration',
  `HasGlassUpgrade` tinyint unsigned NOT NULL DEFAULT '0' COMMENT 'If true, the aircraft has glass regardless of underlying model default',
  `GlassUpgradeDate` datetime DEFAULT NULL COMMENT 'If a glass upgrade has been performed, optionally specifies the date of the upgrade',
  `HasTAAUpgrade` tinyint unsigned NOT NULL COMMENT 'Indicates that this specific aircraft has been upgraded to be TAA per 61.129(j)',
  `PublicNotes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'Notes about the aircraft that are shared among all users.',
  `isLocked` tinyint unsigned NOT NULL COMMENT 'Non-zero if the aircraft is locked for edits (like N1111).',
  `Revision` int NOT NULL DEFAULT '0' COMMENT 'Sequential edit number for this aircraft, for versioning.',
  PRIMARY KEY (`idaircraft`),
  KEY `Tailnumber` (`tailnumber`),
  KEY `Model` (`idmodel`),
  KEY `InstanceType` (`InstanceType`),
  KEY `Tail2` (`tailNormal`),
  CONSTRAINT `fkaircraftinstance` FOREIGN KEY (`InstanceType`) REFERENCES `aircraftinstancetypes` (`ID`) ON DELETE RESTRICT,
  CONSTRAINT `fkaircraftmodel` FOREIGN KEY (`idmodel`) REFERENCES `models` (`idmodel`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='Specific airplanes';
