CREATE TABLE `customcurrency` (
  `idCurrency` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `username` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'Owner of the custom currency',
  `name` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Name of the currency',
  `minEvents` decimal(6,2) unsigned NOT NULL COMMENT 'Number of events that must be counted',
  `limitType` int unsigned DEFAULT '0' COMMENT '0 = minimum events must be met, 1 = no more than maximum',
  `timespan` int unsigned NOT NULL COMMENT 'Timespan in which events must be found',
  `timespanType` int unsigned NOT NULL COMMENT '0 = days, 1 = months',
  `eventType` int unsigned NOT NULL COMMENT 'Type of event to count.',
  `categoryRestriction` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '""' COMMENT 'The category (e.g., "Airplane") to which this applies.',
  `catClassRestriction` int unsigned NOT NULL COMMENT 'If non-zero, only the catclass matters',
  `airportRestriction` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Airport that must be contained in the flight',
  `textRestriction` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Text that must be in the comments field or text property',
  `isinactive` int NOT NULL DEFAULT '0' COMMENT 'Indicates that the currency is inactive.',
  PRIMARY KEY (`idCurrency`),
  KEY `Username` (`username`),
  CONSTRAINT `fkcustomcurrencyuser` FOREIGN KEY (`username`) REFERENCES `users` (`Username`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5905 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Custom currencies for a user';
