DROP TABLE IF EXISTS `flights`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `flights` (
  `idFlight` int unsigned NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL,
  `idaircraft` int unsigned NOT NULL DEFAULT '0',
  `cInstrumentApproaches` int unsigned NOT NULL DEFAULT '0',
  `cLandings` int unsigned NOT NULL DEFAULT '0',
  `crosscountry` decimal(10,4) unsigned NOT NULL DEFAULT '0.0000',
  `night` decimal(10,2) unsigned NOT NULL DEFAULT '0.00',
  `IMC` decimal(10,2) unsigned NOT NULL DEFAULT '0.00',
  `simulatedInstrument` decimal(10,2) unsigned NOT NULL DEFAULT '0.00',
  `dualReceived` decimal(10,2) unsigned NOT NULL DEFAULT '0.00',
  `PIC` decimal(10,2) unsigned NOT NULL DEFAULT '0.00',
  `totalFlightTime` decimal(10,2) unsigned NOT NULL DEFAULT '0.00',
  `fHold` tinyint unsigned NOT NULL DEFAULT '0',
  `Route` varchar(128) DEFAULT NULL,
  `Comments` varchar(16384) DEFAULT NULL,
  `username` varchar(255) NOT NULL DEFAULT '',
  `groundSim` decimal(10,2) DEFAULT NULL,
  `fPublic` tinyint unsigned NOT NULL DEFAULT '0',
  `hobbsStart` decimal(10,2) unsigned DEFAULT NULL,
  `hobbsEnd` decimal(10,2) unsigned DEFAULT NULL,
  `dtEngineStart` datetime DEFAULT NULL,
  `dtEngineEnd` datetime DEFAULT NULL,
  `dtFlightStart` datetime DEFAULT NULL,
  `dtFlightEnd` datetime DEFAULT NULL,
  `cfi` decimal(10,2) unsigned DEFAULT NULL COMMENT 'Instructor time',
  `SIC` decimal(10,2) unsigned DEFAULT NULL,
  `cNightLandings` int unsigned NOT NULL DEFAULT '0',
  `cFullStopLandings` int unsigned NOT NULL DEFAULT '0',
  `idCatClassOverride` int unsigned NOT NULL DEFAULT '0' COMMENT 'ID of overriding category/class for the flight.',
  `telemetry` mediumblob,
  `FlightHash` varchar(2048) DEFAULT NULL COMMENT 'Hash of the flight (for signatures)',
  `SignatureHash` varchar(255) DEFAULT NULL COMMENT 'Encrypted CFIUsername+Certificate+Expiration+SignatureDate, to detect tampering there.',
  `CFIComment` varchar(255) DEFAULT NULL COMMENT 'CFI''s comment',
  `SignatureDate` date DEFAULT NULL COMMENT 'Date of the signature',
  `CFICertificate` varchar(45) DEFAULT NULL COMMENT 'CFI Certificate number',
  `CFIExpiration` date DEFAULT NULL COMMENT 'Expiration of CFI''s certificate',
  `CFIUserName` varchar(255) DEFAULT NULL COMMENT 'Username of CFI',
  `CFIEmail` varchar(255) DEFAULT NULL COMMENT 'Email of CFI at time of signing',
  `CFIName` varchar(65) DEFAULT NULL COMMENT 'Name of CFI at time of signing',
  `DigitizedSignature` mediumblob COMMENT 'Digitization of a signature',
  `SignatureState` int DEFAULT '0' COMMENT 'Digitization of a signature, when no relationship is present.',
  PRIMARY KEY (`idFlight`),
  KEY `DateOfFlight` (`date`),
  KEY `Aircraft` (`idaircraft`),
  KEY `Username` (`username`),
  KEY `fkuseraircraft` (`idaircraft`,`username`),
  CONSTRAINT `fkFlightAircraft` FOREIGN KEY (`idaircraft`) REFERENCES `aircraft` (`idaircraft`) ON DELETE RESTRICT,
  CONSTRAINT `fkFlightUser` FOREIGN KEY (`username`) REFERENCES `users` (`Username`) ON DELETE CASCADE,
  CONSTRAINT `fkuseraircraft` FOREIGN KEY (`idaircraft`, `username`) REFERENCES `useraircraft` (`idAircraft`, `userName`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='Flights I''ve taken';
