--
-- Table structure for table `models`
--

DROP TABLE IF EXISTS `models`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `models` (
  `idmodel` int unsigned NOT NULL AUTO_INCREMENT,
  `idcategoryclass` int unsigned NOT NULL DEFAULT '0',
  `model` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `typename` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `family` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'The family for the model (e.g., PA28-160 and PA28-180 are both PA28''s)',
  `idmanufacturer` int unsigned NOT NULL DEFAULT '0',
  `modelname` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `fcomplex` tinyint(1) NOT NULL DEFAULT '0',
  `fHighPerf` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'True for high performance',
  `f200HP` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Is this model exactly 200HP (was high performance until Aug 4 1997)',
  `fTailwheel` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'True for tailwheel',
  `fConstantProp` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'True for constant speed prop airplanes',
  `fTurbine` tinyint NOT NULL DEFAULT '0' COMMENT 'Non-zero for turbine; 1=Turboprop, 2=Jet',
  `fCertifiedSinglePilot` tinyint(1) NOT NULL COMMENT 'For type-rated turbine aircraft, indicates certification for single-pilot operations.',
  `fRetract` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'True for retract',
  `fCowlFlaps` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Bad name - true if the aircraft has FLAPS, not COWL FLAPS',
  `ArmyMissionDesignSeries` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `fSimOnly` int NOT NULL DEFAULT '0' COMMENT 'If 1, all aircraft with this make/model MUST NOT be real-aircraft.  If 2, can also be generic but real. ',
  `fGlassOnly` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'True if ALL aircraft of this type are glass cockpit',
  `fTAA` tinyint(1) NOT NULL COMMENT 'Indicates that this model is exclusively a Technically Advanced Aircraft per 61.129(j)',
  `fMotorGlider` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'True if this is a motor glider (only applies to gliders)',
  `fMultiHelicopter` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'For helicopters, is this a multi-engine helicopter?',
  PRIMARY KEY (`idmodel`),
  KEY `CatClassID` (`idcategoryclass`),
  KEY `MfctrID` (`idmanufacturer`),
  CONSTRAINT `fkmodelscatclass` FOREIGN KEY (`idcategoryclass`) REFERENCES `categoryclass` (`idCatClass`),
  CONSTRAINT `fkmodelsMan` FOREIGN KEY (`idmanufacturer`) REFERENCES `manufacturers` (`idManufacturer`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='Aircraft Models';
