  CONSTRAINT `fkuseraircraftAc` FOREIGN KEY (`idAircraft`) REFERENCES `aircraft` (`idaircraft`) ON DELETE RESTRICT,
  CONSTRAINT `fkuseraircraftUName` FOREIGN KEY (`userName`) REFERENCES `users` (`Username`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='maps users to aircraft that they fly';
