  `Comment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `FirstName` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `LastName` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Pilot''s mailing address',
  `Password` varchar(128) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL DEFAULT '',
  `PasswordQuestion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `PasswordAnswer` varchar(255) CHARACTER SET latin1 COLLATE latin1_general_ci DEFAULT NULL,
  `IsApproved` tinyint(1) DEFAULT NULL,
  `LastActivityDate` datetime DEFAULT NULL,
  `LastLoginDate` datetime DEFAULT NULL,
  `LastPasswordChangedDate` datetime DEFAULT NULL,
  `CreationDate` datetime DEFAULT NULL,
  `IsOnLine` tinyint(1) DEFAULT NULL,
  `IsLockedOut` tinyint(1) DEFAULT NULL,
  `LastLockedOutDate` datetime DEFAULT NULL,
  `FailedPasswordAttemptCount` int DEFAULT NULL,
  `FailedPasswordAttemptWindowStart` datetime DEFAULT NULL,
  `FailedPasswordAnswerAttemptCount` int DEFAULT NULL,
  `FailedPasswordAnswerAttemptWindowStart` datetime DEFAULT NULL,
  `LastBFR` datetime DEFAULT NULL,
  `LastMedical` datetime DEFAULT NULL,
  `MonthsToMedical` int unsigned NOT NULL DEFAULT '0',
  `IsInstructor` tinyint(1) NOT NULL DEFAULT '1',
  `ShowTimes` tinyint(1) DEFAULT '0',
  `UsesSIC` tinyint(1) NOT NULL DEFAULT '1',
  `UsesHHMM` tinyint unsigned NOT NULL DEFAULT '0',
  `UsesUTCDates` tinyint unsigned NOT NULL DEFAULT '0' COMMENT 'Specifies whether the date-of-flight is a UTC date or a local date.  Default is local date.',
  `DropboxAccesstoken` text CHARACTER SET latin1 COLLATE latin1_general_ci COMMENT 'Access token to be able to write to DropBox',
  `OverwriteDropbox` tinyint unsigned NOT NULL DEFAULT '0' COMMENT 'Overwrite dropbox backup or add new one each time?',
  `OnedriveAccessToken` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `GoogleDriveAccessToken` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `DefaultCloudDriveID` int NOT NULL DEFAULT '0' COMMENT 'Specifies which cloud drive to use if multiple are specified.',
  `CloudAhoyAccessToken` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `License` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Pilot''s license',
  `CertificateNumber` varchar(90) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Pilot certificate number (for instructors)',
  `CFIExpiration` datetime DEFAULT NULL COMMENT 'Expiration date of certificate',
  `EnglishProficiencyExpiration` datetime DEFAULT NULL COMMENT 'Date of English language proficiency expiration',
  `EmailSubscriptions` int unsigned DEFAULT '0' COMMENT 'Bitfield of various email notification subscriptions.',
  `LastEmail` date DEFAULT NULL COMMENT 'Date of last subscribed email to this user',
  `AchievementStatus` tinyint DEFAULT '0' COMMENT 'Current status of achievement computation for this user.',
  `CurrencyFlags` int DEFAULT '0' COMMENT 'Bitflags for special currency attributes - replace UsesArmyCurrency and UsesPerModelCurrency with this.',
  `PropertyBlackList` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'List of property ID''s for properties to explicitly exclude from the Used list.',
  `timezone` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'ID for the preferred timezone for the user',
  `HeadShot` blob COMMENT 'JPEG headshot for the user.',
  `prefs` json DEFAULT NULL COMMENT 'Additional preferences, in JSON dictionary format.',
  `search_text` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci GENERATED ALWAYS AS (concat_ws(_utf8mb4' ',convert(`Username` using utf8mb4),`FirstName`,`LastName`,`Email`)) STORED,
  PRIMARY KEY (`PKID`),
  UNIQUE KEY `Username_UNIQUE` (`Username`),
  KEY `EmailIndex` (`Email`),
  KEY `CreationDate` (`CreationDate`),
  KEY `IsLocked` (`IsLockedOut`),
  FULLTEXT KEY `ft_user_search` (`search_text`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
